{
  "findings": [
    {
      "check_id": "CKV_AZURE_149",
      "title": "Ensure that Virtual machine does not enable password authentication",
      "resource": "azurerm_windows_virtual_machine_scale_set.negative4",
      "severity": "MEDIUM",
      "explanation": "The azurerm_windows_virtual_machine_scale_set resource does not explicitly disable password authentication, which may allow password-based authentication."
    }
  ],
  "patched_code": "resource \"azurerm_windows_virtual_machine_scale_set\" \"negative4\" {\n  name                 = \"negative4-vmss\"\n  resource_group_name  = azurerm_resource_group.negative4.name\n  location             = azurerm_resource_group.negative4.location\n  sku                  = \"Standard_F2\"\n  computer_name_prefix = \"vm-\"\n\n  encryption_at_host_enabled = true\n  disable_password_authentication = true\n}\n",
  "fix_summary": "Added disable_password_authentication = true to the azurerm_windows_virtual_machine_scale_set resource to prevent password-based authentication."
}
